package in.suniye.app;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfDocument;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;import android.widget.*;import org.json.*;import java.io.*;
/** Debug-only recording using synthetic files and actual Android Share intents. */
public final class MediaDemo extends Instrumentation {
 private Uri imageUri,pdfUri;private Bundle args;private Activity activity;private ReaderController reader;private long started;private final JSONArray events=new JSONArray();
 private static final String IMAGE="नमस्ते",PDF="बिल",SECOND="धन्यवाद";
 @Override public void onCreate(Bundle args){this.args=args;start();}
 @Override public void onStart(){Bundle result=new Bundle();started=System.currentTimeMillis();try{
  getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);prepare();
  if("prepare".equals(args.getString("stage"))){JSONArray checks=new JSONArray();String[] samples={"नमस्ते","धन्यवाद","भारत","बिल","कल शाम","चार बजे आइए।","पन्ना दो"};for(String text:samples){PdfDocument sample=new PdfDocument();PdfDocument.Page page=sample.startPage(new PdfDocument.PageInfo.Builder(1000,1200,1).create());page.getCanvas().drawColor(Color.WHITE);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setTextSize(140);paint.setColor(Color.BLACK);page.getCanvas().drawText(text,100,350,paint);sample.finishPage(page);File file=new File(getTargetContext().getCacheDir(),"media-ocr-probe.pdf");try(FileOutputStream out=new FileOutputStream(file)){sample.writeTo(out);}sample.close();Bitmap bitmap=ImageInput.pdfPage(file,0);LocalText.Result inspected=LocalText.inspect(bitmap);bitmap.recycle();checks.put(new JSONObject().put("source",text).put("recognized",inspected.text()).put("lowestConfidence",inspected.lowestConfidence()));file.delete();}write("media-ocr-probe.json",checks.toString(2));result.putString("fixtures",checks.toString());finish(Activity.RESULT_OK,result);return;}
  runOnMainSync(()->{reader=SuniyeApp.reader(getTargetContext());reader.forget();Config c=new Config(getTargetContext());try{c.save(args.getString("endpoint"),args.getString("token"),"demo");}catch(Exception e){throw new RuntimeException(e);}c.acknowledge();c.setOnlineVoice(true);c.setSpeed(.85f);});
  activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();event("home");Thread.sleep(1600);
  event("image-picker");share(imageUri,"image/png");event("image-selected");waitReading(IMAGE);event("image-read-complete");save("media-image-reading.png");Thread.sleep(2300);click("रोकिए");
  runOnMainSync(reader::forget);waitForIdleSync();event("pdf-picker");share(pdfUri,"application/pdf");event("pdf-selected");waitReading(PDF);if(SuniyeApp.document(getTargetContext()).count!=2)throw new AssertionError("PDF count not two");event("pdf-page-one-complete");save("media-pdf-page-one.png");Thread.sleep(2400);
  click("अगला पन्ना");event("pdf-next-page");waitReading(SECOND);if(SuniyeApp.document(getTargetContext()).page!=1)throw new AssertionError("PDF did not advance");event("pdf-page-two-complete");save("media-pdf-page-two.png");Thread.sleep(2000);click("रोकिए");event("stop");
  runOnMainSync(reader::forget);waitForIdleSync();click("WhatsApp से सुनिए");event("whatsapp-help");waitForIdleSync();Thread.sleep(5200);save("media-whatsapp-text-help.png");
  
  // Locate actual top-level help window text; scrolling is through accessibility actions.
  scrollTo("फ़ोटो या PDF खोलें। Share (शेयर) चुनें, फिर ऐप की सूची में सुनिए दबाएँ। किसी संपर्क को भेजने की ज़रूरत नहीं।");event("whatsapp-share-help");Thread.sleep(6000);save("media-whatsapp-share-help.png");
  JSONObject receipt=new JSONObject().put("recordedAt",java.time.Instant.now().toString()).put("environment","Android "+android.os.Build.VERSION.RELEASE+" emulator, font scale "+getTargetContext().getResources().getConfiguration().fontScale).put("imageSource",IMAGE).put("pdfPageOne",PDF).put("pdfPageTwo",SECOND).put("events",events).put("picker","Synthetic ACTION_SEND intents with real MediaStore PNG/PDF content URIs. Share receiver, OCR and paging exercised; no real external WhatsApp sender or completed file-picker test.").put("reading","Bundled OCR, actual backend Hindi TTS and MediaPlayer; base rate 1, playback .85").put("whatsapp","Actual Suniye help screen only; no WhatsApp account or real WhatsApp integration test");write("media-demo-receipt.json",receipt.toString(2));result.putString("demo","PASS: image/PDF share intents, OCR and Raju playback, second PDF page, Stop and labelled WhatsApp help");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){try{write("media-demo-failure.json",new JSONObject().put("events",events).put("failure",e.toString()).toString(2));}catch(Exception ignored){}result.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,result);}}
 private void prepare()throws Exception{
  Bitmap bitmap=Bitmap.createBitmap(1000,700,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(bitmap);c.drawColor(Color.WHITE);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(Color.BLACK);p.setTextSize(140);c.drawText(IMAGE,100,300,p);File image=new File(getTargetContext().getFilesDir(),"media-note.png");try(FileOutputStream out=new FileOutputStream(image)){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();imageUri=store(image,"Suniye-note.png","image/png");
  PdfDocument pdf=new PdfDocument();for(int i=0;i<2;i++){PdfDocument.Page page=pdf.startPage(new PdfDocument.PageInfo.Builder(1000,1200,i+1).create());page.getCanvas().drawColor(Color.WHITE);if(i==0){page.getCanvas().drawText(PDF,100,350,p);}else page.getCanvas().drawText(SECOND,100,350,p);pdf.finishPage(page);}File file=new File(getTargetContext().getFilesDir(),"media-two-pages.pdf");try(FileOutputStream out=new FileOutputStream(file)){pdf.writeTo(out);}pdf.close();pdfUri=store(file,"Suniye-two-pages.pdf","application/pdf");
 }
 private Uri store(File file,String name,String type)throws Exception{android.database.Cursor old=getTargetContext().getContentResolver().query(MediaStore.Downloads.EXTERNAL_CONTENT_URI,new String[]{MediaStore.Downloads._ID},MediaStore.Downloads.DISPLAY_NAME+"=?",new String[]{name},null);if(old!=null){try{while(old.moveToNext())getTargetContext().getContentResolver().delete(ContentUris.withAppendedId(MediaStore.Downloads.EXTERNAL_CONTENT_URI,old.getLong(0)),null,null);}finally{old.close();}}ContentValues values=new ContentValues();values.put(MediaStore.Downloads.DISPLAY_NAME,name);values.put(MediaStore.Downloads.MIME_TYPE,type);values.put(MediaStore.Downloads.RELATIVE_PATH,Environment.DIRECTORY_DOWNLOADS);Uri uri=getTargetContext().getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("Fixture insert failed");try(InputStream in=new FileInputStream(file);OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){byte[] buffer=new byte[8192];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);}return uri;}
 private void waitReading(String expected)throws Exception{long end=System.currentTimeMillis()+35000;do{waitForIdleSync();if(!reader.busy()&&reader.hasLast()){String normalized=reader.original().replaceAll("\\s+","");if(!normalized.equals(expected.replaceAll("\\s+","")))throw new AssertionError("OCR differs: "+reader.original());if(!reader.status().startsWith("फिर सुनने")||!new File(getTargetContext().getFilesDir(),"last-reading.mp3").exists())throw new AssertionError("Online speech did not complete: "+reader.status());if(getTargetContext().getSharedPreferences("last-reading",Context.MODE_PRIVATE).getFloat("audioBaseRate",0)!=1)throw new AssertionError("Unexpected voice base rate");return;}if(!reader.busy()&&!reader.status().startsWith("रोक दिया"))throw new AssertionError("Reading failed: "+reader.status());Thread.sleep(100);}while(System.currentTimeMillis()<end);throw new AssertionError("Reading timed out");}
 private void share(Uri uri,String type)throws Exception{runOnMainSync(()->activity.startActivity(new Intent(Intent.ACTION_SEND).setClass(getTargetContext(),MainActivity.class).setType(type).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_GRANT_READ_URI_PERMISSION)));waitForIdleSync();}
 private void scrollTo(String text)throws Exception{for(int i=0;i<8;i++){AccessibilityNodeInfo root=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES).getRootInActiveWindow();if(root==null)throw new AssertionError("No help window");AccessibilityNodeInfo n=find(root,text);if(n!=null&&n.isVisibleToUser()){n.recycle();root.recycle();return;}if(n!=null)n.recycle();AccessibilityNodeInfo scroll=scrollable(root);root.recycle();if(scroll==null)throw new AssertionError("No help scroll");scroll.performAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD);scroll.recycle();Thread.sleep(500);}throw new AssertionError("Help section not reached");}
 private AccessibilityNodeInfo find(AccessibilityNodeInfo n,String text){if((n.getText()!=null&&text.contentEquals(n.getText()))||(n.getContentDescription()!=null&&(text.contentEquals(n.getContentDescription())||n.getContentDescription().toString().startsWith(text+","))))return AccessibilityNodeInfo.obtain(n);for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo c=n.getChild(i);if(c!=null){AccessibilityNodeInfo found=find(c,text);c.recycle();if(found!=null)return found;}}return null;}
 private AccessibilityNodeInfo scrollable(AccessibilityNodeInfo n){if(n.isScrollable())return AccessibilityNodeInfo.obtain(n);for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo c=n.getChild(i);if(c!=null){AccessibilityNodeInfo found=scrollable(c);c.recycle();if(found!=null)return found;}}return null;}
 private void click(String label)throws Exception{runOnMainSync(()->{Button b=findButton(activity.getWindow().getDecorView(),label);if(b==null)throw new AssertionError("Missing button "+label);b.requestRectangleOnScreen(new Rect(0,0,b.getWidth(),b.getHeight()),true);});waitForIdleSync();Thread.sleep(350);runOnMainSync(()->findButton(activity.getWindow().getDecorView(),label).performClick());}
 private Button findButton(View view,String text){if(view instanceof Button&&text.contentEquals(((Button)view).getText()))return(Button)view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)view;for(int i=0;i<g.getChildCount();i++){Button b=findButton(g.getChildAt(i),text);if(b!=null)return b;}}return null;}
 private void event(String name)throws Exception{events.put(new JSONObject().put("name",name).put("elapsedMs",System.currentTimeMillis()-started));}
 private void write(String name,String text)throws Exception{try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name))){out.write(text.getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
 private void save(String name)throws Exception{Bitmap b=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES).takeScreenshot();if(b==null)throw new AssertionError("Screenshot absent");try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name))){b.compress(Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}
}
